steps.script:
var am = PhaseManager.get_current_phase_instance().active_moves.get("U_WAZDAKKA_GUTSMEK_A", {})
print("[wp-g3] pulse jet: roll ", am.get("pulse_roll", -1), " cap ", am.get("move_cap_inches", -1))
return str(am.get("mode", ""))

var am = PhaseManager.get_current_phase_instance().active_moves.get("U_WAZDAKKA_GUTSMEK_A", {})
var r = int(am.get("pulse_roll", 0))
return r >= 1 and r <= 6 and is_equal_approx(float(am.get("move_cap_inches", 0)), 18.0 + r) and bool(am.get("mode_locked", false))

var l = tree.root.get_node("Main/HUD_Right/VBoxContainer/MovementScrollContainer/MovementPanel/Section3_ModeSelection/AdvanceRollLabel")
print("[wp-g3] label: ", l.text)
return l.text.begins_with("Pulse Roll:")

var ph = PhaseManager.get_current_phase_instance()
var m = GameState.get_unit("U_WAZDAKKA_GUTSMEK_A").models[0]
var p = Vector2(m.position.x, m.position.y)
return ph._path_crosses_enemy_bases(p, p + Vector2(0, 740), "U_WAZDAKKA_GUTSMEK_A", m)

var am = PhaseManager.get_current_phase_instance().active_moves.get("U_WAZDAKKA_GUTSMEK_A", {})
var st = am.get("staged_moves", [])
print("[wp-g3] staged: ", st)
return st.size() == 1 and float(st[0].dest.y) > 1000.0

var ab = RulesEngine.ork11e_ab_mods(GameState.get_unit("U_CUSTODIAN_GUARD_B"), GameState.get_unit("U_WAZDAKKA_GUTSMEK_A"), {"name": "guardian spear", "type": "Ranged", "range": 24}, false, GameState.state)
print("[wp-g3] mods vs Wazdakka: ", ab.get("sources", []))
return bool(ab.hit_minus) and ab.sources.any(func(s): return s.name == "Pulse Jet")
